-- t170: booking_170_osoite_saunotus_fi (kb.productsin vanha kehitysosoite → https://saunotus.fi) ja sen rollback.
-- Ajo (psql, paikallinen PG17, jossa migraatiot on ajettu mock-kantaan; ks. booking/supabase/tests/run.sh):
--   cd booking/supabase/tests/kb && psql -X -v ON_ERROR_STOP=0 -f t170_osoite_saunotus_fi.sql
-- Lähtötila = tuotannon tila 24.10.2026 (SELECT, sxbofnuisemspgquoxyv): tuotteiden 1, 7, 25, 26, 38, 50 kentät description, description_en,
-- short_description(_en), booking_url, source_url sekä booking.site_texts product.<id>.description [fi/en] (julkaistu teksti, versio,
-- needs_translation). Julkisia tuotekuvauksia, ei asiakastietoja.
-- A lähtötila, B vartija (poikkeava teksti → exception, ei muutoksia), C migraatio (+ needs_translation ennallaan), D uudelleenajo,
-- E rollback (täsmälleen alkuperäinen + needs_translation ennallaan), F rollbackin uudelleenajo, G rollbackin vartija,
-- H migraatio uudelleen rollbackin jälkeen, I needs_translation-vartija. Kaikki yhdessä transaktiossa; lopussa tahallinen poikkeus
-- "TESTRESULT pass=… fail=…" kumoaa kaiken. Ei tuotantoon.
-- Odotettu poikkeus tarkistetaan näin: savepoint → \ir → nextval('t170_noerr') → rollback to savepoint → ck(sekvenssi ennallaan).
-- Jos poikkeus tuli, nextval ei suoritu (transaktio keskeytetty); sekvenssi ei peruunnu rollbackissa, joten puuttuva poikkeus näkyy.
begin;
create temp table t170_r(ok boolean, label text);
create temp sequence t170_noerr;
select nextval('t170_noerr');
create function pg_temp.ck(ok boolean, label text) returns void language sql as $$ insert into t170_r values (coalesce(ok, false), label) $$;
-- mock-kannasta (fixtures/kb_mock.sql) puuttuvat tuotannon sarakkeet
alter table kb.products add column if not exists source_url text, add column if not exists short_description text, add column if not exists short_description_en text;
-- tuotannon tekstit ilman synkkatriggeriä (booking.text_apply = on → zz_site_text_sync ohittaa)
select set_config('booking.text_apply', 'on', true);
update kb.products set description = $k170$<h3>Yleinen sauna – sekavuoro, johon kaikki ovat tervetulleita!</h3><p>Tule nauttimaan yhteisöllisestä saunaelämyksestä ja savusaunamme täyteläisistä löylyistä. Saunavuoro sisältää pääsyn sauna-alueelle, virkistäviin kylmä- ja lämminvesialtaisiin sekä rauhalliselle laavulle, joka on vapaasti käytettävissäsi sauna-ajan puitteissa.</p><p><strong>Saunavuorot ja aikataulut:</strong></p><ul><li><strong>Viikonloppuisin</strong> (lauantai ja sunnuntai): Saunomisaika on <strong>kaksi tuntia</strong>. Paikka on aina varattava etukäteen. Viikonloppuisin saunomme uima-asussa.</li><li>Jos pidät kuumista löylyistä, tule ensimmäisten vuorojen aikana. Jos taas olet lempeämpien löylyjen ystävä, varaa paikka viimeisestä vuorosta tai tule oman porukan kanssa <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">jälkilöylyille</a>.</li><li><strong>Torstaisin</strong>: Sauna-alue on avoinna yleiselle vuorolle klo <strong>17–19</strong>. Torstain vuorolla uima-asu on vapaaehtoinen.</li></ul><p><strong>Muista varustautua!</strong></p><ul><li>Tuo oma <strong>pyyhe ja tossut</strong>.</li><li>Voit myös vuokrata tai ostaa pyyhkeen, saunatakin tai tossut paikan päältä (pyyhe- ja tossuvuokra: 5 €).</li><li>Talviaikaan suosittelemme <strong>saunatakkia ja pipoa</strong>, jotta pysyt lämpimänä löylyjen välissä.</li></ul><p>Sauna-alueella sijaitsee hirsimökki, jossa on suihku. Mökin lähistöllä käytettävissäsi on perinteinen huussi. Saunallamme on myös laavu, jota asiakkaamme saavat käyttää sauna-ajan puitteissa.</p>$k170$, description_en = $k170$<h3>Public sauna – a mixed session where everyone is welcome!</h3><p>Come and enjoy a shared sauna experience and the rich löyly of our smoke sauna. The session includes access to the sauna area, the refreshing cold and hot water tubs and the peaceful lean-to shelter (laavu), which is yours to use freely during your sauna time.</p><p><strong>Sauna sessions and schedules:</strong></p><ul><li><strong>At weekends</strong> (Saturday and Sunday): Sauna time is <strong>two hours</strong>. A place must always be booked in advance. At weekends we bathe in swimwear.</li><li>If you like hot löyly, come during the first sessions. If you prefer gentler löyly, book a place in the last session or come with your own group for the <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">After Session Sauna (jälkilöylyt)</a>.</li><li><strong>On Thursdays</strong>: The sauna area is open for a public session from <strong>17–19</strong>. On the Thursday session, swimwear is optional.</li></ul><p><strong>Remember to come prepared!</strong></p><ul><li>Bring your own <strong>towel and slippers</strong>.</li><li>You can also rent or buy a towel, sauna robe or slippers on site (towel and slipper rental: 5 €).</li><li>In winter we recommend <strong>a sauna robe and a woolly hat</strong> to keep you warm between rounds of löyly.</li></ul><p>In the sauna area there is a log cabin with a shower. Near the cabin there is a traditional outdoor toilet (huussi) for your use. Our sauna also has a lean-to shelter that our guests are welcome to use during their sauna time.</p>$k170$, short_description = $k170$<p>Ota ystävät tai perhe mukaan ja tule nauttimaan yhteisöllisestä saunaelämyksestä sekä savusaunamme pehmeistä löylyistä ja upeasta miljööstä.</p>$k170$, short_description_en = $k170$<p>Bring your friends or family and come and enjoy a shared sauna experience, the soft löyly of our smoke sauna and its wonderful setting.</p>$k170$, booking_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yleinen-sauna/yleinensauna$k170$, source_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yleinen-sauna/yleinensauna$k170$ where id = 1;
update kb.products set description = $k170$<h3><strong>Tee sukellus itämerensuomalaiseen saunaperinteeseen!</strong></h3><p>Tule nauttimaan yhteisöllisestä saunaelämyksestä ja itämerensuomalaisesta saunaperinteestä. Saunavuoro sisältää pääsyn sauna-alueelle, virkistäviin kylmä- ja lämminvesialtaisiin sekä rauhalliselle laavulle, joka on vapaasti käytettävissäsi sauna-ajan puitteissa. Vuoro alkaa 20 minuutin saunarituaalilla hoitosauna Raunissa, josta siirrymme savusaunan puolelle nauttimaan pehmeistä ja viipyilevistä löylyistä.</p><p>Rituaaliin voi halutessaan tulla alasti, mutta savusaunassa ja paljuissa käytetään uima-asuja.</p><p>Sisältää:</p><ul><li>Löylyntervehdyksen</li><li>Kevyttä lämmittelyvihdontaa</li><li>Vuodenkierron mukaisen minihoidon</li></ul><p><strong>Saunavuorot ja aikataulut:</strong></p><ul><li>Elämys alkaa hoitosauna Raunissa <strong>20 minuutin saunotusrituaalilla</strong></li><li>Saunomisaika savusaunassa on <strong>1h 40 min</strong>.</li></ul><p><strong>Muista varustautua!</strong></p><ul><li>Tuo oma <strong>pyyhe, tossut ja uima-asu</strong>.</li><li>Voit myös vuokrata tai ostaa pyyhkeen, saunatakin tai tossut paikan päältä (pyyhe- ja tossuvuokra: 5 €).</li><li>Talviaikaan suosittelemme <strong>saunatakkia ja pipoa</strong>, jotta pysyt lämpimänä löylyjen välissä.</li></ul><p>Sauna-alueella sijaitsee hirsimökki, jossa on suihku. Mökin lähistöllä käytettävissäsi on perinteinen huussi. Saunallamme on myös laavu, jota asiakkaamme saavat käyttää sauna-ajan puitteissa.</p><h2><a href="https://uusi.saunotus.com/varaa/#/">Jos haluat tehdä varauksen elämyslahjojen lahjakortilla niin varaa ensin vuoro tästä ja osta rituaali erikseen</a></h2>$k170$, description_en = $k170$<h3><strong>Dive into the Baltic Finnic sauna tradition!</strong></h3><p>Come and enjoy a shared sauna experience and the Baltic Finnic sauna tradition. The session includes access to the sauna area, the refreshing cold and hot water tubs and the peaceful lean-to shelter (laavu), which is yours to use freely during your sauna time. The session begins with a 20-minute sauna ritual in the treatment sauna Rauni, after which we move over to the smoke sauna to enjoy its soft, lingering löyly.</p><p>You may come to the ritual naked if you wish, but swimwear is worn in the smoke sauna and the tubs.</p><p>Includes:</p><ul><li>A löyly greeting (löylyntervehdys)</li><li>Light warm-up birch whisking (vihdonta)</li><li>A mini treatment following the cycle of the year</li></ul><p><strong>Sauna sessions and schedules:</strong></p><ul><li>The experience begins in the treatment sauna Rauni with a <strong>20-minute guided sauna ritual (saunotusrituaali)</strong></li><li>Sauna time in the smoke sauna is <strong>1h 40 min</strong>.</li></ul><p><strong>Remember to come prepared!</strong></p><ul><li>Bring your own <strong>towel, slippers and swimwear</strong>.</li><li>You can also rent or buy a towel, sauna robe or slippers on site (towel and slipper rental: 5 €).</li><li>In winter we recommend <strong>a sauna robe and a woolly hat</strong> to keep you warm between rounds of löyly.</li></ul><p>In the sauna area there is a log cabin with a shower. Near the cabin there is a traditional outdoor toilet (huussi) for your use. Our sauna also has a lean-to shelter that our guests are welcome to use during their sauna time.</p><h2><a href="https://uusi.saunotus.com/varaa/#/">If you want to book with an Elämyslahjat gift card, first book a session here and buy the ritual separately</a></h2>$k170$, short_description = $k170$<p>Ota ystävät tai perhe mukaan ja tule nauttimaan savusaunamme upeasta miljööstä ja itämerensuomalaisesta saunarituaalista</p>$k170$, short_description_en = $k170$<p>Bring your friends or family and come and enjoy the wonderful setting of our smoke sauna and a Baltic Finnic sauna ritual</p>$k170$, booking_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yleinen-sauna/saunarituaali-ja-savusaunavuoro$k170$, source_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yleinen-sauna/saunarituaali-ja-savusaunavuoro$k170$ where id = 7;
update kb.products set description = $k170$<p>Onko tiedossa ilta ystävien kanssa, synttärit tai vaikka polttarit? Vuokraa koko Sipoonjoen perinnesaunan miljöö omaan käyttöösi! </p><p>Varaukseen sisältyy savusaunan lisäksi lämmin- ja kylmävesialtaat sekä alueella olevan laavun ja hirsimökin vapaa käyttö.</p><p>Haluamme tukea perheiden ja kaveriporukoiden saunakulttuuria, joten nämä hinnat ovat voimassa ainoastaan yksityishenkilöille. <a href="https://uusi.saunotus.com/yritykset/">Katso tästä palvelumme yrityksille!</a></p>$k170$, description_en = $k170$<p>Planning an evening with friends, a birthday or perhaps a hen or stag party? Rent the whole Sipoonjoen perinnesauna setting for yourselves! </p><p>In addition to the smoke sauna, your booking includes the hot and cold water tubs and free use of the lean-to shelter (laavu) and the log cabin in the area.</p><p>We want to support the sauna culture of families and groups of friends, so these prices apply to private individuals only. <a href="https://uusi.saunotus.com/yritykset/">See our services for businesses here!</a></p>$k170$, short_description = $k170$<p>Savusauna, paljut, laavu ja hirsimökki omaan käyttöön. Voit vuokrata tilat omaan käyttöön ennen yleisiä vuoroja tai vaikkapa ihan koko päiväksi.</p>$k170$, short_description_en = $k170$<p>The smoke sauna, tubs, lean-to shelter (laavu) and log cabin all to yourselves. You can rent the facilities for your own use before the public sessions or even for the whole day.</p>$k170$, booking_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yksityisvuorot/oma-saunavuoro$k170$, source_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yksityisvuorot/oma-saunavuoro$k170$ where id = 25;
update kb.products set description = $k170$<p>Yleisten vuorojen jälkeen on mahdollisuus nauttia viipyilevistä ja pehmeistä jälkilöylyistä klo 19 alkaen klo 21 saakka viikolla ja klo 22 saakka viikonloppuisin.</p><p>Pakettiin kuuluu savusauna, lämmin- ja kylmävesialtaat sekä laavun vapaa käyttö. Jälkilöylyt otetaan aina huomioon lämmitysvaiheessa ja takaamme, että saunassa ei tarvitse palella, vaikka savusaunan jälkilöylyt ovatkin kosteat ja pehmeät.</p><p>Perushinta sisältää 6 osallistujaa, tämän jälkeen veloitus on 10€ / hlö.</p><p>Haluamme tukea perheiden ja kaveriporukoiden saunakulttuuria, joten nämä hinnat ovat voimassa ainoastaan yksityishenkilöille. Katso <a href="https://uusi.saunotus.com/yritykset/">tästä palvelumme yrityksille!</a></p>$k170$, description_en = $k170$<p>After the public sessions, you can enjoy the lingering, soft After Session Sauna (jälkilöylyt) from 19 until 21 on weekdays and until 22 at weekends.</p><p>The package includes the smoke sauna, the hot and cold water tubs and free use of the lean-to shelter (laavu). The After Session Sauna is always taken into account when the sauna is heated, and we guarantee you won't feel cold in the sauna, even though the after-session löyly of a smoke sauna is moist and soft.</p><p>The base price includes 6 participants; after that the charge is 10€ / person.</p><p>We want to support the sauna culture of families and groups of friends, so these prices apply to private individuals only. See <a href="https://uusi.saunotus.com/yritykset/">our services for businesses here!</a></p>$k170$, short_description = $k170$<p>Yleisten vuorojen jälkeen on mahdollisuus nauttia viipyilevistä ja pehmeistä jälkilöylyistä edullisesti!</p>$k170$, short_description_en = $k170$<p>After the public sessions, you can enjoy the lingering, soft After Session Sauna (jälkilöylyt) at an affordable price!</p>$k170$, booking_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yksityisvuorot/jalkiloylyt$k170$, source_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/yksityisvuorot/jalkiloylyt$k170$ where id = 26;
update kb.products set description = $k170$<p><strong>Lunasta saunaelämys – täydellinen lahja rentoutumiseen</strong></p><p>Valitse lahjakortin arvo ja ilahduta läheistäsi rentouttavalla saunaelämyksellä. Lahjakortti on arvolahjakortti, eikä sitä ole sidottu mihinkään tiettyyn tuotteeseen. Sen voi käyttää vapaasti <strong>kaikkiin palveluihimme</strong>, ja lahjakortilla voi maksaa myös osan arvokkaammasta elämyksestä.</p><p>Lahjakortti on voimassa <strong>kuusi kuukautta ostohetkestä</strong>, ja se voidaan toimittaa helposti suoraan vastaanottajalle.</p><p>Jos lahjakorttia ei ehditä käyttää voimassaoloaikana, vastaanottaja voi ottaa meihin yhteyttä sähköpostitse joustavien järjestelyjen sopimiseksi.</p><p>Anna lahjaksi unohtumaton hetki luonnon rauhassa – lämpimien löylyjen, rentouttavien altaiden ja saunan rauhoittavan tunnelman parissa.</p><p><strong>Tässä esimerkkejä saunaelämystemme ja hoitojemme hinnoista:</strong></p><ul><li>29 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Yleinen saunavuoro yhdelle</a></li><li>58 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Yleinen saunavuoro kahdelle</a></li><li>99 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito yhdelle (1 h)</a></li><li>134 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito kahdelle (1 h)</a></li><li>169 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito kolmelle (1 h)</a></li><li>180–300 € <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">Savusaunan yksityiset jälkilöylyt (2–3 h)</a></li><li>204 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito neljälle (1 h)</a></li><li>210 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Saunotus yhdelle (2 h)</a></li><li>270 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Saunotus kahdelle (2 h)</a></li><li>290 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Syväsaunotus yhdelle (3 h)</a></li><li>360 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Syväsaunotus kahdelle (3 h)</a></li></ul><p><strong>Lahjan saaja päättää itse, mihin elämykseen lahjakorttinsa käyttää.</strong> Lahjakortin arvon voi valita vapaasti, eikä sen tarvitse vastata minkään yksittäisen palvelun hintaa.</p>$k170$, description_en = $k170$<p><strong>Give a sauna experience – the perfect gift for relaxation</strong></p><p>Choose the value of the gift card and delight someone close to you with a relaxing sauna experience. This is a value gift card and is not tied to any particular product. It can be used freely for <strong>all our services</strong>, and it can also be used to pay part of a more expensive experience.</p><p>The gift card is valid for <strong>six months from the date of purchase</strong>, and it can easily be delivered directly to the recipient.</p><p>If the gift card can't be used within its validity period, the recipient can contact us by email to agree on flexible arrangements.</p><p>Give the gift of an unforgettable moment in the peace of nature – with warm löyly, relaxing tubs and the soothing atmosphere of the sauna.</p><p><strong>Here are some examples of the prices of our sauna experiences and treatments:</strong></p><ul><li>29 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Public sauna session for one</a></li><li>58 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Public sauna session for two</a></li><li>99 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for one (1 h)</a></li><li>134 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for two (1 h)</a></li><li>169 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for three (1 h)</a></li><li>180–300 € <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">Private After Session Sauna (jälkilöylyt) in the smoke sauna (2–3 h)</a></li><li>204 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for four (1 h)</a></li><li>210 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Guided sauna session (saunotus) for one (2 h)</a></li><li>270 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Guided sauna session for two (2 h)</a></li><li>290 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Deep guided sauna session (syväsaunotus) for one (3 h)</a></li><li>360 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Deep guided sauna session for two (3 h)</a></li></ul><p><strong>The recipient decides which experience to use the gift card for.</strong> The value of the gift card can be chosen freely and does not need to match the price of any single service.</p>$k170$, short_description = $k170$<p><strong>Lunasta saunaelämys – täydellinen lahja rentoutumiseen! </strong>Valitse itse lahjakortin arvo ja ilahduta läheistäsi rentouttavalla saunaelämyksellä.</p>$k170$, short_description_en = $k170$<p><strong>Give a sauna experience – the perfect gift for relaxation! </strong>Choose the value of the gift card yourself and delight someone close to you with a relaxing sauna experience.</p>$k170$, booking_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/sarja-ja-lahjakortit/lahjakortti$k170$, source_url = $k170$https://sipoonjoenperinnesauna.johku.com/fi_FI/sarja-ja-lahjakortit/lahjakortti$k170$ where id = 38;
update kb.products set description = $k170$<p>Savusauna tarjoaa ympäristön työhyvinvointipäiville, pienryhmille ja yhteisille saunailloille. Saunavuorojen, rituaalien ja hoitojen lisäksi päivään voidaan yhdistää esim. metsäkävely, metsäjooga, eräruokailu laavulla tai vihdansidontatyöpaja. Hinnat tarjouspyynnöstä.</p>$k170$, description_en = $k170$<p>The smoke sauna offers a setting for workplace well-being days, small groups and shared sauna evenings. In addition to sauna sessions, rituals and treatments, the day can be combined with, for example, a forest walk, forest yoga, an outdoor meal at the lean-to shelter (laavu) or a birch whisk-binding workshop. Prices on request.</p>$k170$, short_description = null, short_description_en = null, booking_url = null, source_url = $k170$https://uusi.saunotus.com/$k170$ where id = 50;
update booking.site_texts set published_text = $k170$<h3>Yleinen sauna – sekavuoro, johon kaikki ovat tervetulleita!</h3><p>Tule nauttimaan yhteisöllisestä saunaelämyksestä ja savusaunamme täyteläisistä löylyistä. Saunavuoro sisältää pääsyn sauna-alueelle, virkistäviin kylmä- ja lämminvesialtaisiin sekä rauhalliselle laavulle, joka on vapaasti käytettävissäsi sauna-ajan puitteissa.</p><p><strong>Saunavuorot ja aikataulut:</strong></p><ul><li><strong>Viikonloppuisin</strong> (lauantai ja sunnuntai): Saunomisaika on <strong>kaksi tuntia</strong>. Paikka on aina varattava etukäteen. Viikonloppuisin saunomme uima-asussa.</li><li>Jos pidät kuumista löylyistä, tule ensimmäisten vuorojen aikana. Jos taas olet lempeämpien löylyjen ystävä, varaa paikka viimeisestä vuorosta tai tule oman porukan kanssa <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">jälkilöylyille</a>.</li><li><strong>Torstaisin</strong>: Sauna-alue on avoinna yleiselle vuorolle klo <strong>17–19</strong>. Torstain vuorolla uima-asu on vapaaehtoinen.</li></ul><p><strong>Muista varustautua!</strong></p><ul><li>Tuo oma <strong>pyyhe ja tossut</strong>.</li><li>Voit myös vuokrata tai ostaa pyyhkeen, saunatakin tai tossut paikan päältä (pyyhe- ja tossuvuokra: 5 €).</li><li>Talviaikaan suosittelemme <strong>saunatakkia ja pipoa</strong>, jotta pysyt lämpimänä löylyjen välissä.</li></ul><p>Sauna-alueella sijaitsee hirsimökki, jossa on suihku. Mökin lähistöllä käytettävissäsi on perinteinen huussi. Saunallamme on myös laavu, jota asiakkaamme saavat käyttää sauna-ajan puitteissa.</p>$k170$, published_version = 5, latest_version = 5, status = 'published', needs_translation = false where key = 'product.1.description' and lang = 'fi';
update booking.site_texts set published_text = $k170$<h3><strong>Tee sukellus itämerensuomalaiseen saunaperinteeseen!</strong></h3><p>Tule nauttimaan yhteisöllisestä saunaelämyksestä ja itämerensuomalaisesta saunaperinteestä. Saunavuoro sisältää pääsyn sauna-alueelle, virkistäviin kylmä- ja lämminvesialtaisiin sekä rauhalliselle laavulle, joka on vapaasti käytettävissäsi sauna-ajan puitteissa. Vuoro alkaa 20 minuutin saunarituaalilla hoitosauna Raunissa, josta siirrymme savusaunan puolelle nauttimaan pehmeistä ja viipyilevistä löylyistä.</p><p>Rituaaliin voi halutessaan tulla alasti, mutta savusaunassa ja paljuissa käytetään uima-asuja.</p><p>Sisältää:</p><ul><li>Löylyntervehdyksen</li><li>Kevyttä lämmittelyvihdontaa</li><li>Vuodenkierron mukaisen minihoidon</li></ul><p><strong>Saunavuorot ja aikataulut:</strong></p><ul><li>Elämys alkaa hoitosauna Raunissa <strong>20 minuutin saunotusrituaalilla</strong></li><li>Saunomisaika savusaunassa on <strong>1h 40 min</strong>.</li></ul><p><strong>Muista varustautua!</strong></p><ul><li>Tuo oma <strong>pyyhe, tossut ja uima-asu</strong>.</li><li>Voit myös vuokrata tai ostaa pyyhkeen, saunatakin tai tossut paikan päältä (pyyhe- ja tossuvuokra: 5 €).</li><li>Talviaikaan suosittelemme <strong>saunatakkia ja pipoa</strong>, jotta pysyt lämpimänä löylyjen välissä.</li></ul><p>Sauna-alueella sijaitsee hirsimökki, jossa on suihku. Mökin lähistöllä käytettävissäsi on perinteinen huussi. Saunallamme on myös laavu, jota asiakkaamme saavat käyttää sauna-ajan puitteissa.</p><h2><a href="https://uusi.saunotus.com/varaa/#/">Jos haluat tehdä varauksen elämyslahjojen lahjakortilla niin varaa ensin vuoro tästä ja osta rituaali erikseen</a></h2>$k170$, published_version = 6, latest_version = 6, status = 'published', needs_translation = false where key = 'product.7.description' and lang = 'fi';
update booking.site_texts set published_text = $k170$<p>Onko tiedossa ilta ystävien kanssa, synttärit tai vaikka polttarit? Vuokraa koko Sipoonjoen perinnesaunan miljöö omaan käyttöösi! </p><p>Varaukseen sisältyy savusaunan lisäksi lämmin- ja kylmävesialtaat sekä alueella olevan laavun ja hirsimökin vapaa käyttö.</p><p>Haluamme tukea perheiden ja kaveriporukoiden saunakulttuuria, joten nämä hinnat ovat voimassa ainoastaan yksityishenkilöille. <a href="https://uusi.saunotus.com/yritykset/">Katso tästä palvelumme yrityksille!</a></p>$k170$, published_version = 4, latest_version = 4, status = 'published', needs_translation = true where key = 'product.25.description' and lang = 'fi';
update booking.site_texts set published_text = $k170$<p>Yleisten vuorojen jälkeen on mahdollisuus nauttia viipyilevistä ja pehmeistä jälkilöylyistä klo 19 alkaen klo 21 saakka viikolla ja klo 22 saakka viikonloppuisin.</p><p>Pakettiin kuuluu savusauna, lämmin- ja kylmävesialtaat sekä laavun vapaa käyttö. Jälkilöylyt otetaan aina huomioon lämmitysvaiheessa ja takaamme, että saunassa ei tarvitse palella, vaikka savusaunan jälkilöylyt ovatkin kosteat ja pehmeät.</p><p>Perushinta sisältää 6 osallistujaa, tämän jälkeen veloitus on 10€ / hlö.</p><p>Haluamme tukea perheiden ja kaveriporukoiden saunakulttuuria, joten nämä hinnat ovat voimassa ainoastaan yksityishenkilöille. Katso <a href="https://uusi.saunotus.com/yritykset/">tästä palvelumme yrityksille!</a></p>$k170$, published_version = 4, latest_version = 4, status = 'published', needs_translation = true where key = 'product.26.description' and lang = 'fi';
update booking.site_texts set published_text = $k170$<p>Savusauna tarjoaa ympäristön työhyvinvointipäiville, pienryhmille ja yhteisille saunailloille. Saunavuorojen, rituaalien ja hoitojen lisäksi päivään voidaan yhdistää esim. metsäkävely, metsäjooga, eräruokailu laavulla tai vihdansidontatyöpaja. Hinnat tarjouspyynnöstä.</p>$k170$, published_version = 2, latest_version = 2, status = 'published', needs_translation = false where key = 'product.50.description' and lang = 'fi';
update booking.site_texts set published_text = $k170$<p><strong>Lunasta saunaelämys – täydellinen lahja rentoutumiseen</strong></p><p>Valitse lahjakortin arvo ja ilahduta läheistäsi rentouttavalla saunaelämyksellä. Lahjakortti on arvolahjakortti, eikä sitä ole sidottu mihinkään tiettyyn tuotteeseen. Sen voi käyttää vapaasti <strong>kaikkiin palveluihimme</strong>, ja lahjakortilla voi maksaa myös osan arvokkaammasta elämyksestä.</p><p>Lahjakortti on voimassa <strong>kuusi kuukautta ostohetkestä</strong>, ja se voidaan toimittaa helposti suoraan vastaanottajalle.</p><p>Jos lahjakorttia ei ehditä käyttää voimassaoloaikana, vastaanottaja voi ottaa meihin yhteyttä sähköpostitse joustavien järjestelyjen sopimiseksi.</p><p>Anna lahjaksi unohtumaton hetki luonnon rauhassa – lämpimien löylyjen, rentouttavien altaiden ja saunan rauhoittavan tunnelman parissa.</p><p><strong>Tässä esimerkkejä saunaelämystemme ja hoitojemme hinnoista:</strong></p><ul><li>29 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Yleinen saunavuoro yhdelle</a></li><li>58 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Yleinen saunavuoro kahdelle</a></li><li>99 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito yhdelle (1 h)</a></li><li>134 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito kahdelle (1 h)</a></li><li>169 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito kolmelle (1 h)</a></li><li>180–300 € <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">Savusaunan yksityiset jälkilöylyt (2–3 h)</a></li><li>204 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Saunahoito neljälle (1 h)</a></li><li>210 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Saunotus yhdelle (2 h)</a></li><li>270 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Saunotus kahdelle (2 h)</a></li><li>290 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Syväsaunotus yhdelle (3 h)</a></li><li>360 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Syväsaunotus kahdelle (3 h)</a></li></ul><p><strong>Lahjan saaja päättää itse, mihin elämykseen lahjakorttinsa käyttää.</strong> Lahjakortin arvon voi valita vapaasti, eikä sen tarvitse vastata minkään yksittäisen palvelun hintaa.</p>$k170$, published_version = 4, latest_version = 4, status = 'published', needs_translation = false where key = 'product.38.description' and lang = 'fi';
update booking.site_texts set published_text = $k170$<h3>Public sauna – a mixed session where everyone is welcome!</h3><p>Come and enjoy a shared sauna experience and the rich löyly of our smoke sauna. The session includes access to the sauna area, the refreshing cold and hot water tubs and the peaceful lean-to shelter (laavu), which is yours to use freely during your sauna time.</p><p><strong>Sauna sessions and schedules:</strong></p><ul><li><strong>At weekends</strong> (Saturday and Sunday): Sauna time is <strong>two hours</strong>. A place must always be booked in advance. At weekends we bathe in swimwear.</li><li>If you like hot löyly, come during the first sessions. If you prefer gentler löyly, book a place in the last session or come with your own group for the <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">After Session Sauna (jälkilöylyt)</a>.</li><li><strong>On Thursdays</strong>: The sauna area is open for a public session from <strong>17–19</strong>. On the Thursday session, swimwear is optional.</li></ul><p><strong>Remember to come prepared!</strong></p><ul><li>Bring your own <strong>towel and slippers</strong>.</li><li>You can also rent or buy a towel, sauna robe or slippers on site (towel and slipper rental: 5 €).</li><li>In winter we recommend <strong>a sauna robe and a woolly hat</strong> to keep you warm between rounds of löyly.</li></ul><p>In the sauna area there is a log cabin with a shower. Near the cabin there is a traditional outdoor toilet (huussi) for your use. Our sauna also has a lean-to shelter that our guests are welcome to use during their sauna time.</p>$k170$, published_version = 5, latest_version = 5, status = 'published', needs_translation = true where key = 'product.1.description' and lang = 'en';
update booking.site_texts set published_text = $k170$<h3><strong>Dive into the Baltic Finnic sauna tradition!</strong></h3><p>Come and enjoy a shared sauna experience and the Baltic Finnic sauna tradition. The session includes access to the sauna area, the refreshing cold and hot water tubs and the peaceful lean-to shelter (laavu), which is yours to use freely during your sauna time. The session begins with a 20-minute sauna ritual in the treatment sauna Rauni, after which we move over to the smoke sauna to enjoy its soft, lingering löyly.</p><p>You may come to the ritual naked if you wish, but swimwear is worn in the smoke sauna and the tubs.</p><p>Includes:</p><ul><li>A löyly greeting (löylyntervehdys)</li><li>Light warm-up birch whisking (vihdonta)</li><li>A mini treatment following the cycle of the year</li></ul><p><strong>Sauna sessions and schedules:</strong></p><ul><li>The experience begins in the treatment sauna Rauni with a <strong>20-minute guided sauna ritual (saunotusrituaali)</strong></li><li>Sauna time in the smoke sauna is <strong>1h 40 min</strong>.</li></ul><p><strong>Remember to come prepared!</strong></p><ul><li>Bring your own <strong>towel, slippers and swimwear</strong>.</li><li>You can also rent or buy a towel, sauna robe or slippers on site (towel and slipper rental: 5 €).</li><li>In winter we recommend <strong>a sauna robe and a woolly hat</strong> to keep you warm between rounds of löyly.</li></ul><p>In the sauna area there is a log cabin with a shower. Near the cabin there is a traditional outdoor toilet (huussi) for your use. Our sauna also has a lean-to shelter that our guests are welcome to use during their sauna time.</p><h2><a href="https://uusi.saunotus.com/varaa/#/">If you want to book with an Elämyslahjat gift card, first book a session here and buy the ritual separately</a></h2>$k170$, published_version = 5, latest_version = 5, status = 'published', needs_translation = true where key = 'product.7.description' and lang = 'en';
update booking.site_texts set published_text = $k170$<p>Planning an evening with friends, a birthday or perhaps a hen or stag party? Rent the whole Sipoonjoen perinnesauna setting for yourselves! </p><p>In addition to the smoke sauna, your booking includes the hot and cold water tubs and free use of the lean-to shelter (laavu) and the log cabin in the area.</p><p>We want to support the sauna culture of families and groups of friends, so these prices apply to private individuals only. <a href="https://uusi.saunotus.com/yritykset/">See our services for businesses here!</a></p>$k170$, published_version = 3, latest_version = 3, status = 'published', needs_translation = false where key = 'product.25.description' and lang = 'en';
update booking.site_texts set published_text = $k170$<p>After the public sessions, you can enjoy the lingering, soft After Session Sauna (jälkilöylyt) from 19 until 21 on weekdays and until 22 at weekends.</p><p>The package includes the smoke sauna, the hot and cold water tubs and free use of the lean-to shelter (laavu). The After Session Sauna is always taken into account when the sauna is heated, and we guarantee you won't feel cold in the sauna, even though the after-session löyly of a smoke sauna is moist and soft.</p><p>The base price includes 6 participants; after that the charge is 10€ / person.</p><p>We want to support the sauna culture of families and groups of friends, so these prices apply to private individuals only. See <a href="https://uusi.saunotus.com/yritykset/">our services for businesses here!</a></p>$k170$, published_version = 4, latest_version = 4, status = 'published', needs_translation = false where key = 'product.26.description' and lang = 'en';
update booking.site_texts set published_text = $k170$<p>The smoke sauna offers a setting for workplace well-being days, small groups and shared sauna evenings. In addition to sauna sessions, rituals and treatments, the day can be combined with, for example, a forest walk, forest yoga, an outdoor meal at the lean-to shelter (laavu) or a birch whisk-binding workshop. Prices on request.</p>$k170$, published_version = 3, latest_version = 3, status = 'published', needs_translation = true where key = 'product.50.description' and lang = 'en';
update booking.site_texts set published_text = $k170$<p><strong>Give a sauna experience – the perfect gift for relaxation</strong></p><p>Choose the value of the gift card and delight someone close to you with a relaxing sauna experience. This is a value gift card and is not tied to any particular product. It can be used freely for <strong>all our services</strong>, and it can also be used to pay part of a more expensive experience.</p><p>The gift card is valid for <strong>six months from the date of purchase</strong>, and it can easily be delivered directly to the recipient.</p><p>If the gift card can't be used within its validity period, the recipient can contact us by email to agree on flexible arrangements.</p><p>Give the gift of an unforgettable moment in the peace of nature – with warm löyly, relaxing tubs and the soothing atmosphere of the sauna.</p><p><strong>Here are some examples of the prices of our sauna experiences and treatments:</strong></p><ul><li>29 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Public sauna session for one</a></li><li>58 € <a href="https://uusi.saunotus.com/varaa/#/?k=yleinen">Public sauna session for two</a></li><li>99 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for one (1 h)</a></li><li>134 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for two (1 h)</a></li><li>169 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for three (1 h)</a></li><li>180–300 € <a href="https://uusi.saunotus.com/varaa/#/tuote/jalkiloylyt">Private After Session Sauna (jälkilöylyt) in the smoke sauna (2–3 h)</a></li><li>204 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunahoito-2">Sauna treatment for four (1 h)</a></li><li>210 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Guided sauna session (saunotus) for one (2 h)</a></li><li>270 € <a href="https://uusi.saunotus.com/varaa/#/tuote/saunotus-2">Guided sauna session for two (2 h)</a></li><li>290 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Deep guided sauna session (syväsaunotus) for one (3 h)</a></li><li>360 € <a href="https://uusi.saunotus.com/varaa/#/tuote/syvasaunotus">Deep guided sauna session for two (3 h)</a></li></ul><p><strong>The recipient decides which experience to use the gift card for.</strong> The value of the gift card can be chosen freely and does not need to match the price of any single service.</p>$k170$, published_version = 3, latest_version = 3, status = 'published', needs_translation = true where key = 'product.38.description' and lang = 'en';
delete from booking.site_text_versions where text_id in (select id from booking.site_texts where source_table = 'kb.products' and key ~ '^product\.(1|7|25|26|38|50)\.description$');
insert into booking.site_text_versions(text_id, version, text, status, base_version, author_kind, author_label, reason, published_at, escalation, protected)
select id, published_version, published_text, 'published', 0, 'system', 't170', 'tuotannon tila 24.10.2026', now(), '{}', false
  from booking.site_texts where source_table = 'kb.products' and key ~ '^product\.(1|7|25|26|38|50)\.description$' and published_version > 0;
select set_config('booking.text_apply', '', true);
-- lähtötilan liput talteen (vertailu C/D/E/F/H)
create temp table t170_nt as select id, key, lang, needs_translation from booking.site_texts where source_table = 'kb.products' and key ~ '^product\.(1|7|25|26|38|50)\.description$';
create temp view t170_nt_same as select count(*) = 12 and bool_and(st.needs_translation = b.needs_translation) ok from t170_nt b join booking.site_texts st using (id);
create temp table t170_f(pid int, col text, from_md5 text, to_md5 text);
