create function pg_temp.state(p_to boolean) returns boolean language sql as $$
  select bool_and(md5(coalesce(to_jsonb(p) ->> f.col, '')) = case when p_to then f.to_md5 else f.from_md5 end) from t170_f f join kb.products p on p.id = f.pid $$;
create function pg_temp.nver() returns bigint language sql as $$
  select count(*) from booking.site_text_versions v join booking.site_texts t on t.id = v.text_id where t.source_table = 'kb.products' and t.key ~ '^product\.(1|7|25|26|38|50)\.description$' $$;
create temp table t170_n(step text, n bigint);
insert into t170_n values ('A', pg_temp.nver());

select pg_temp.ck(pg_temp.state(false), 'A1: lähtötila = tuotannon tekstit (11 kenttää, md5)');
select pg_temp.ck((select count(*) from kb.products where concat_ws(' ', description, description_en, short_description, short_description_en, booking_url, source_url) like '%uusi.saunotus.com%') = 6, 'A2: 6 tuotteessa vanha osoite');
select pg_temp.ck((select sum((length(coalesce(to_jsonb(p) ->> f.col, '')) - length(replace(coalesce(to_jsonb(p) ->> f.col, ''), 'https://uusi.saunotus.com', ''))) / 25) from t170_f f join kb.products p on p.id = f.pid) = 31, 'A3: 31 osoitetta');
select pg_temp.ck((select string_agg(key || ':' || lang || '=' || needs_translation, ',' order by key, lang) from t170_nt) = 'product.1.description:en=true,product.1.description:fi=false,product.25.description:en=false,product.25.description:fi=true,product.26.description:en=false,product.26.description:fi=true,product.38.description:en=true,product.38.description:fi=false,product.50.description:en=true,product.50.description:fi=false,product.7.description:en=true,product.7.description:fi=false', 'A4: needs_translation = tuotannon tila');
select pg_temp.ck(not exists (select 1 from booking.site_texts st join kb.products p on p.id::text = st.source_pk where st.source_table = 'kb.products' and st.key ~ '^product\.(1|7|25|26|38|50)\.description$' and st.published_text <> coalesce(to_jsonb(p) ->> st.source_column, '')), 'A5: sivutekstit = lähdetaulu');

-- B: vartija – tuotteen 38 kuvaus poikkeaa yhdellä välilyönnillä → exception ennen yhtään muutosta
select set_config('booking.text_apply', 'on', true);
update kb.products set description = description || ' ' where id = 38;
select set_config('booking.text_apply', '', true);
savepoint b;
\ir ../../migrations/20261024201634_booking_170_osoite_saunotus_fi.sql
select nextval('t170_noerr');
rollback to savepoint b;
select pg_temp.ck((select last_value from t170_noerr) = 1, 'B0: vartija – poikkeus tuli (ei muutoksia)');
select set_config('booking.text_apply', 'on', true);
update kb.products set description = left(description, -1) where id = 38;
select set_config('booking.text_apply', '', true);
select pg_temp.ck(pg_temp.state(false) and pg_temp.nver() = (select n from t170_n where step = 'A') and (select ok from t170_nt_same), 'B1: poikkeama → ei muutoksia (tekstit, versiot, liput)');

-- C: migraatio
\ir ../../migrations/20261024201634_booking_170_osoite_saunotus_fi.sql
select pg_temp.ck(pg_temp.state(true), 'C1: kaikki 11 kenttää = odotettu uusi teksti (md5)');
select pg_temp.ck(not exists (select 1 from kb.products where concat_ws(' ', description, description_en, short_description, short_description_en, booking_url, source_url) like '%uusi.saunotus.com%'), 'C2: ei vanhaa osoitetta kb.productsissa');
select pg_temp.ck(pg_temp.nver() = (select n from t170_n where step = 'A') + 10, 'C3: 10 uutta sivutekstiversiota (tuotteet 1, 7, 25, 26, 38 × fi/en)');
select pg_temp.ck(not exists (select 1 from booking.site_texts st join kb.products p on p.id::text = st.source_pk where st.source_table = 'kb.products' and st.key ~ '^product\.(1|7|25|26|38|50)\.description$' and st.published_text <> coalesce(to_jsonb(p) ->> st.source_column, '')), 'C4: sivutekstit synkassa');
select pg_temp.ck((select ok from t170_nt_same), 'C5: needs_translation täsmälleen sama kuin ennen ajoa (12 riviä)');
select pg_temp.ck((select needs_translation from booking.site_texts where key = 'product.1.description' and lang = 'fi') = false and (select needs_translation from booking.site_texts where key = 'product.38.description' and lang = 'fi') = false, 'C6: fi 1/38 ei käännöstarvetta osoitevaihdon takia');
insert into t170_n values ('C', pg_temp.nver());

-- D: uudelleenajo – ei muutoksia
\ir ../../migrations/20261024201634_booking_170_osoite_saunotus_fi.sql
select pg_temp.ck(pg_temp.state(true) and pg_temp.nver() = (select n from t170_n where step = 'C') and (select ok from t170_nt_same), 'D1: uudelleenajo ei muuta mitään');

-- E: rollback
\ir ../../rollbacks/20261024201634_booking_170_ROLLBACK.sql
select pg_temp.ck(pg_temp.state(false), 'E1: rollback = täsmälleen alkuperäiset tekstit (md5)');
select pg_temp.ck((select count(*) from kb.products where concat_ws(' ', description, description_en, short_description, short_description_en, booking_url, source_url) like '%uusi.saunotus.com%') = 6, 'E2: 6 tuotetta taas vanhalla osoitteella');
select pg_temp.ck((select ok from t170_nt_same), 'E3: needs_translation täsmälleen sama kuin ennen booking_170:tä');
select pg_temp.ck(pg_temp.nver() = (select n from t170_n where step = 'C') + 10, 'E4: rollback kirjaa 10 versiota (historia säilyy)');
select pg_temp.ck(not exists (select 1 from booking.site_texts st join kb.products p on p.id::text = st.source_pk where st.source_table = 'kb.products' and st.key ~ '^product\.(1|7|25|26|38|50)\.description$' and st.published_text <> coalesce(to_jsonb(p) ->> st.source_column, '')), 'E5: sivutekstit synkassa');
insert into t170_n values ('E', pg_temp.nver());

-- F: rollbackin uudelleenajo – ei muutoksia
\ir ../../rollbacks/20261024201634_booking_170_ROLLBACK.sql
select pg_temp.ck(pg_temp.state(false) and pg_temp.nver() = (select n from t170_n where step = 'E') and (select ok from t170_nt_same), 'F1: rollbackin uudelleenajo ei muuta mitään');

-- G: rollbackin vartija – migraation jälkeen muokattu kenttä → exception
\ir ../../migrations/20261024201634_booking_170_osoite_saunotus_fi.sql
select set_config('booking.text_apply', 'on', true);
update kb.products set description_en = description_en || ' ' where id = 25;
select set_config('booking.text_apply', '', true);
savepoint g;
\ir ../../rollbacks/20261024201634_booking_170_ROLLBACK.sql
select nextval('t170_noerr');
rollback to savepoint g;
select pg_temp.ck((select last_value from t170_noerr) = 1, 'G0: rollbackin vartija – poikkeus tuli (ei muutoksia)');
select pg_temp.ck((select md5(description) from kb.products where id = 1) = (select to_md5 from t170_f where pid = 1 and col = 'description'), 'G1: rollbackin poikkeama → ei muutoksia');
select set_config('booking.text_apply', 'on', true);
update kb.products set description_en = left(description_en, -1) where id = 25;
select set_config('booking.text_apply', '', true);

-- H: migraatio rollbackin jälkeen uudelleen (G:n alussa) → loppu sama kuin C
select pg_temp.ck(pg_temp.state(true) and (select ok from t170_nt_same), 'H1: rollback → migraatio uudelleen: tekstit ja liput oikein');

-- I: needs_translation-vartija – lippu muuttui, mutta rivin julkaistu teksti ei ole tämän migraation tulos → exception
\ir ../../rollbacks/20261024201634_booking_170_ROLLBACK.sql
select pg_temp.ck(pg_temp.state(false) and (select ok from t170_nt_same), 'I0: rollback ennen I-testiä');
savepoint i;
-- testin sisäinen tynkä (peruuntuu): trigger, joka nostaa toisen kielen lipun mutta ei synkkaa tekstiä → lipun palautus ei saa tapahtua
create or replace function booking._text_source_changed() returns trigger language plpgsql set search_path to '' as $f$
begin
  update booking.site_texts set needs_translation = true where source_table = 'kb.products' and source_pk = new.id::text and key = 'product.' || new.id || '.description' and lang = 'fi';
  return null;
end $f$;
\ir ../../migrations/20261024201634_booking_170_osoite_saunotus_fi.sql
select nextval('t170_noerr');
rollback to savepoint i;
select pg_temp.ck((select last_value from t170_noerr) = 1, 'I1: needs_translation-vartija – poikkeus tuli (ei muutoksia)');
select pg_temp.ck(pg_temp.state(false) and (select ok from t170_nt_same) and md5(pg_get_functiondef('booking._text_source_changed()'::regprocedure)) = '2b770706e4cfa97b40cb952e8926c77b', 'I2: vartijan poikkeus → kb.products ja liput ennallaan, oikea trigger palautunut');

select * from t170_r where not ok;
do $t$ declare p int; f int; begin
  select count(*) filter (where ok), count(*) filter (where not ok) into p, f from t170_r;
  raise exception 'TESTRESULT pass=% fail=%', p, f;
end $t$;
rollback;
